          className="relative w-[95vw] sm:w-full max-w-3xl max-h-[85vh] sm:max-h-[90vh] bg-[#050505] rounded-none border border-white/20 overflow-hidden shadow-2xl p-5 sm:p-8 flex flex-col justify-between"
        >
